def solve_n_queens(n):
    """Solve the N-Queens problem using backtracking."""
    def is_safe(board, row, col):
        # Check this row on left side
        for i in range(col):
            if board[row] == i:
                return False

        # Check upper diagonal on left side
        for i, j in zip(range(row, -1, -1), range(col, -1, -1)):
            if board[i] == j:
                return False

        # Check lower diagonal on left side
        for i, j in zip(range(row, n, 1), range(col, -1, -1)):
            if board[i] == j:
                return False

        return True

    def solve(board, col):
        if col >= n:
            return True

        for row in range(n):
            if is_safe(board, row, col):
                board[row] = col
                if solve(board, col + 1):
                    return True
                board[row] = -1

        return False

    board = [-1] * n
    if solve(board, 0):
        return board
    return None

# Actually, let me use a more standard approach where board[i] = column of queen in row i
def solve_n_queens_v2(n):
    """Solve N-Queens where result[i] = column position of queen in row i."""
    def backtrack(row, cols, diag1, diag2, solution):
        if row == n:
            return solution[:]

        for col in range(n):
            d1 = row - col  # diagonal 1 (row - col is constant)
            d2 = row + col  # diagonal 2 (row + col is constant)

            if col not in cols and d1 not in diag1 and d2 not in diag2:
                cols.add(col)
                diag1.add(d1)
                diag2.add(d2)
                solution[row] = col

                result = backtrack(row + 1, cols, diag1, diag2, solution)
                if result is not None:
                    return result

                cols.remove(col)
                diag1.remove(d1)
                diag2.remove(d2)
                solution[row] = -1

        return None

    solution = [-1] * n
    return backtrack(0, set(), set(), set(), solution)

