    # Verify the solution
    def verify_solution(sol, n):
        for i in range(n):
            for j in range(i+1, n):
                # Same column
                if sol[i] == sol[j]:
                    return False
                # Same diagonal
                if abs(sol[i] - sol[j]) == abs(i - j):
                    return False
        return True

    print(f"Verification: {verify_solution(solution, 26)}")
